package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.AssigneeVO;

class AssigneeValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of assignee of observed issue")
  void test_assignee_value_holder_assign_plain_value() {
    Object holder = new Object();
    AssigneeValueHolder<Object> value = new AssigneeValueHolder<>(holder);
    Assertions.assertSame(holder, value.assignee("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getAssigneeValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getAssignee().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.assigneeNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getAssigneeValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getAssignee().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of assignee of observed issue")
  void test_assignee_value_holder_assign_value_object() {
    Object holder = new Object();
    AssigneeValueHolder<Object> value = new AssigneeValueHolder<>(holder);
    AssigneeVO vo = AssigneeVO.from("one");
    Assertions.assertFalse(value.getAssigneeValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.assignee(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getAssigneeValue().orElseThrow());
    Assertions.assertSame(holder, value.assignee(Optional.empty()));
    Assertions.assertFalse(value.getAssigneeValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.assignee(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAssigneeValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of assignee of observed issue against the original")
  void test_assignee_value_holder_read() {
    Object holder = new Object();
    AssigneeValueHolder<Object> value = new AssigneeValueHolder<>(holder);
    AssigneeVO vo = AssigneeVO.from("one");
    AssigneeVO other = AssigneeVO.from("one");
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getAssigneeValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAssignee(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readAssignee(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.assignee(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAssignee(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAssignee(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of assignee of observed issue")
  void test_assignee_value_holder_unset() {
    Object holder = new Object();
    AssigneeValueHolder<Object> value = new AssigneeValueHolder<>(holder);
    AssigneeVO vo = AssigneeVO.from("one");
    value.assignee(vo);
    Assertions.assertSame(holder, value.unsetAssigneeIfMatches("assignee_other"));
    Assertions.assertTrue(value.getAssigneeValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetAssigneeIfMatches("assignee"));
    Assertions.assertFalse(value.getAssigneeValue().isPresent(),
        "The field name must clear the value");
    value.assignee(vo);
    Assertions.assertSame(holder, value.unsetAssignee());
    Assertions.assertFalse(value.getAssigneeValue().isPresent(), "Unset must clear the value");
  }
}
